1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;
8	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
9	
10	/**
11	 * Step of {@code POST /api/owners} that rejects a create whose telephone is already used by an
12	 * existing owner, throwing {@link DuplicateTelephoneException} (handled as 409 Conflict). Runs after
13	 * {@link RequireOwnerFields} has normalized the telephone to E.164 form and published the body, and
14	 * before {@link BuildOwner}/{@link SaveOwner} persist the new owner. Duplicates are detected by
15	 * comparing the canonical E.164 values.
16	 */
17	public class RequireUniqueTelephone {
18	
19	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
20	            throws DuplicateTelephoneException {
21	        String telephone = request.getTelephone(); // already E.164 (set by RequireOwnerFields)
22	        for (Owner existing : ownerRepository.findAll()) {
23	            if (telephone.equals(normalize(existing.getTelephone()))) {
24	                throw new DuplicateTelephoneException(
25	                        "Telephone " + telephone + " is already used by another owner");
26	            }
27	        }
28	    }
29	
30	    private static String normalize(String telephone) {
31	        try {
32	            return OwnerTelephone.toE164(telephone);
33	        }
34	        catch (InvalidTelephoneException ex) {
35	            return telephone == null ? "" : telephone;
36	        }
37	    }
38	}
