3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.DuplicateEmailException;
10	
11	/**
12	 * Step of {@code POST /api/owners} that rejects a create whose email is already used by an existing
13	 * owner, throwing {@link DuplicateEmailException} (handled as 409 Conflict). Runs after
14	 * {@link RequireOwnerFields} has normalized the email to its trimmed, lower-cased form and published
15	 * the body, and before {@link BuildOwner}/{@link SaveOwner} persist the new owner. Email is optional:
16	 * a request without an email is never a duplicate. Duplicates are detected by comparing lower-cased
17	 * values.
18	 */
19	public class RequireUniqueEmail {
20	
21	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
22	            throws DuplicateEmailException {
23	        String email = request.getEmail(); // already trimmed and lower-cased by RequireOwnerFields
24	        if (email == null || email.isBlank()) {
25	            return; // email is optional; absent email is never a duplicate
26	        }
27	        for (Owner existing : ownerRepository.findAll()) {
28	            if (email.equals(normalize(existing.getEmail()))) {
29	                throw new DuplicateEmailException(
30	                        "Email " + email + " is already used by another owner");
31	            }
32	        }
33	    }
34	
35	    private static String normalize(String email) {
36	        return email == null ? null : email.trim().toLowerCase(Locale.ROOT);
37	    }
38	}
