1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
4	
5	/**
6	 * Shared normalization of an owner telephone to E.164 form. Spaces, dashes and brackets are
7	 * stripped. A leading {@code '+'} and its country code are kept as supplied; otherwise the default
8	 * country code {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the
9	 * national digits. The result must carry 8 to 15 digits after the {@code '+'}, or the value is
10	 * rejected as invalid.
11	 *
12	 * <p>The national-number length is also checked against the country code: {@code '+61'} requires 9
13	 * national digits and {@code '+1'} requires 10. A wrong length for the country is rejected.
14	 *
15	 * <p>Examples: {@code "0412 345 678" -> "+61412345678"}, {@code "+64 21 123 456" -> "+6421123456"}.
16	 */
17	final class OwnerTelephone {
18	
19	    private OwnerTelephone() {
20	    }
21	
22	    /**
23	     * @return the canonical E.164 telephone (a {@code '+'} followed by 8-15 digits).
24	     * @throws InvalidTelephoneException when the value cannot form a valid E.164 number.
25	     */
26	    static String toE164(String telephone) throws InvalidTelephoneException {
27	        if (telephone == null) {
28	            throw invalid();
29	        }
30	        // Strip spaces, dashes and brackets; any other non-digit survives and fails the check below.
31	        String stripped = telephone.replaceAll("[\\s()\\-]", "");
32	        String e164;
33	        if (stripped.startsWith("+")) {
34	            e164 = "+" + stripped.substring(1);
35	        }
36	        else {
37	            String national = stripped;
38	            if (national.startsWith("0")) {
39	                national = national.substring(1);
40	            }
41	            e164 = "+61" + national;
42	        }
43	        String digits = e164.substring(1);
44	        if (!digits.matches("[0-9]{8,15}")) {
45	            throw invalid();
46	        }
47	        // Per-country national-number length. Only the country codes with a known fixed length are
48	        // enforced; others keep the generic 8-15 digit rule above.
49	        if (e164.startsWith("+61")) {
50	            requireNationalLength(e164, "+61", 9);
51	        }
52	        else if (e164.startsWith("+1")) {
53	            requireNationalLength(e164, "+1", 10);
54	        }
55	        return e164;
56	    }
57	
58	    private static void requireNationalLength(String e164, String countryCode, int nationalDigits)
59	            throws InvalidTelephoneException {
60	        // e164 is '+' + all digits; drop the leading '+' and the country code to get the national part.
61	        int national = e164.length() - 1 - (countryCode.length() - 1);
62	        if (national != nationalDigits) {
63	            throw new InvalidTelephoneException("Telephone with country code " + countryCode
64	                    + " must have " + nationalDigits + " national digits");
65	        }
66	    }
67	
68	    private static InvalidTelephoneException invalid() {
69	        return new InvalidTelephoneException(
70	                "Telephone must form a valid E.164 number with 8 to 15 digits after the country code");
71	    }
72	}
