package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;

/**
 * The single derived identity of a pet owner, consolidating every duplicate-detection field into one
 * key. The {@code identityKey} is {@code normalizedTelephone + '|' + (email or empty) + '|' +
 * householdId}, where the telephone is canonical E.164 form, the email is trimmed and lower-cased (or
 * empty when absent) and the household id is {@link Household#id(String, String)} over the last name
 * and address. Two owners are duplicates only when their whole keys are equal, so members of the same
 * household with different telephones (or emails) have distinct keys and are both allowed.
 *
 * <p>Used by {@link RequireUniqueIdentity} to reject an exact-key collision and by the owner mapper
 * to expose the key on responses.
 */
public final class OwnerIdentity {

    private OwnerIdentity() {
    }

    /** The identity key for an owner with the given raw fields. Fields are normalized here so the
     *  same value is produced whether they come from a freshly-validated request or a stored owner. */
    public static String key(String telephone, String email, String lastName, String address) {
        return normalizeTelephone(telephone) + "|" + normalizeEmail(email) + "|"
                + Household.id(lastName, address);
    }

    private static String normalizeTelephone(String telephone) {
        try {
            return OwnerTelephone.toE164(telephone);
        }
        catch (InvalidTelephoneException ex) {
            return telephone == null ? "" : telephone;
        }
    }

    private static String normalizeEmail(String email) {
        if (email == null || email.isBlank()) {
            return "";
        }
        return email.trim().toLowerCase(Locale.ROOT);
    }
}

