package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;

/**
 * Step of {@code POST /api/owners} that rejects a create whose whole {@code identityKey} (see
 * {@link OwnerIdentity}) equals an existing owner's, throwing {@link DuplicateIdentityException}
 * (handled as 409 Conflict). This is the single, consolidated duplicate check: the former separate
 * telephone, email and household checks are all expressed through this one key. Because the telephone
 * is part of the key, two members of the same household with different telephones have different keys
 * and are both allowed; only an exact full-key match is a duplicate.
 *
 * <p>Runs after {@link RequireOwnerFields} has normalized and published the body and before
 * {@link BuildOwner}/{@link SaveOwner} persist the new owner.
 */
public class RequireUniqueIdentity {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateIdentityException {
        String identityKey = OwnerIdentity.key(request.getTelephone(), request.getEmail(),
                request.getLastName(), request.getAddress());
        for (Owner existing : ownerRepository.findAll()) {
            String existingKey = OwnerIdentity.key(existing.getTelephone(), existing.getEmail(),
                    existing.getLastName(), existing.getAddress());
            if (identityKey.equals(existingKey)) {
                throw new DuplicateIdentityException(
                        "An owner with the same identity already exists");
            }
        }
    }
}

